(
  '55555555-5555-4555-8555-555555555555',
  'local_page',
  'turkish-restaurant',
  'Turkish and Mediterranean Restaurant in San Francisco',
  'Visit Turquaz on Mission Street for Turkish and Mediterranean breakfast, lunch, dinner, pastries and coffee in San Francisco.',
  '[{"type":"paragraph","text":"Turquaz brings Turkish cooking, Mediterranean ingredients, bakery traditions and warm hospitality together at 1198 Mission Street in San Francisco. Guests can join us for breakfast, lunch or dinner, meet over coffee, or share a table of meze and grilled dishes."},{"type":"heading","level":2,"text":"Turkish food for different moments of the day"},{"type":"paragraph","text":"The menu moves from Turkish breakfast and fresh pastries to soups, salads, bowls, pide, kebabs and shareable feasts. Coffee, tea and desserts offer a reason to stay after the main meal. Because selections and prices may change, our live menu is the most current guide."},{"type":"heading","level":2,"text":"A table designed for sharing"},{"type":"paragraph","text":"Turkish dining is especially rewarding when several dishes meet at the center of the table. Begin with meze, add bread or a flatbread, and choose grilled plates or vegetable dishes to share. This format gives each guest room to discover different textures and flavors."},{"type":"heading","level":2,"text":"Visit Turquaz on Mission Street"},{"type":"list","ordered":false,"items":["Address: 1198 Mission St, San Francisco, CA 94102","Phone: +1 415-791-0770","Turkish and Mediterranean cuisine","Breakfast, lunch and dinner reservations","Online ordering and catering options"]},{"type":"heading","level":2,"text":"Reserve or order online"},{"type":"paragraph","text":"Use the Turquaz website to reserve a table for up to 15 guests or follow the online-ordering link for current pickup and delivery choices. For larger parties, catering or private-event questions, contact the restaurant directly."}]',
  'published',
  'Turkish Restaurant in San Francisco | Turquaz',
  'Visit Turquaz, a Turkish and Mediterranean restaurant on Mission Street in San Francisco. View the menu, reserve or order online.',
